import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"訟","description":"東坡易傳 - 訟","frontmatter":{"title":"訟","description":"東坡易傳 - 訟"},"headers":[],"relativePath":"classics/dongpo/007.md","filePath":"classics/dongpo/007.md"}'),o={name:"classics/dongpo/007.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="訟" tabindex="-1">訟 <a class="header-anchor" href="#訟" aria-label="Permalink to “訟”">​</a></h1><p>“訟”：有孚，窒，惕，中吉；終兇。利見大人，不利涉大川。</p><p>《彖》曰：“訟”，上剛下險，險而健，訟。“訟，有孚，窒，惕，中吉”，剛來而得中也。“終兇”，訟不可成也。</p><p>初六信於九四，六三信於上九，而九二塞之，故曰：“有孚，窒。”而九四、上九亦不能置而不爭，此“訟”之所以作也。故曰：“上剛下險，險而健，訟。”九二知懼，則猶可以免，故曰：“惕，中吉。”“剛來而得中也”，言其來則息“訟”而歸矣，終之則兇。“利見大人”，尚中正也。謂九五也。“不利涉大川”，入於淵也。夫使川為淵者，“訟”之過也。天下之難①，未有不起於爭，今又欲以爭濟之，是使相激為深而已。</p><p>【校注】 ① 天下之難：原文無“天下之”三字，依《蘇氏易傳》補。</p><p>象曰：天與水違行，“訟”，君子以作事謀始。</p><p>王弼曰：“‘聽訟，吾猶人也；必也使無訟乎？’夫無訟，在於謀始。”“契之不明，訟之所以生也，”“故有德司契，”而“訟”自息矣。</p><p>初六：不永所事，小有言，終吉。</p><p>九二處二陰之間，欲兼有之，初不予而強爭焉。初六有應於四，不永事二而之四以為從；強求之二，不若從有應之四也。二雖“有言”，而其辨則明，故“終吉”。象曰：“不永所事”，訟不可長也。雖“小有言”，其辯明也。若事二，則相從於訟無已也。</p><p>九二：不克訟，歸。而逋其邑人三百戶，無眚。象曰：“不克訟，歸。”“逋”，竄也。自下訟上，患至掇也。</p><p>初六、六三，本非九二之所當有也。二以其近而強有之，以為邑人力征而心不服我，克則來，不克遂往，以我卜也。故九二“不克訟”而歸。則初六、六三皆棄而違之。失眾知懼，猶可少安，故“無眚”。“眚”，災也。其曰“逋其邑人三百戶”者，猶曰亡其邑人三百戶雲耳。</p><p>六三：食舊德，貞厲，終吉。或從王事，無成。象曰：“食舊德”，從上吉也。</p><p>六三與上九為應，二與四欲得之，而強施德焉。夫六三之應於上九者，天命之所當有也，非為其有德於我也，雖二與四之德不能奪之矣。是以“食舊德”，以從其配①，“食”者，食而忘之、不報之謂也，猶若食言云耳。與二陽近而不報其德，故厲而後吉。“或從王事，無成”者，有討於其舊，從之可也；成之，過矣。</p><p>【校注】 ① “不從其配”，原作“以從其配”，據《蘇氏易傳》改。</p><p>九四：不克訟，復即命，渝，安貞吉。象曰：“復即命，渝”，安貞不失也。</p><p>九四命之所當得者，初六而已。近於三而強求之，故亦“不克訟”。然而有初之應，退而就其命之所當得者，自改而安於貞，則猶可以不失其有也。</p><p>九五：訟，元吉象曰：“訟，元吉”，以中正也。</p><p>處中得位而無私於應，故訟者莫不取曲直焉。此所以為“元吉”也。</p><p>上九：或錫之鞶帶，終朝三褫之。象曰：以訟受服，亦不足敬也。</p><p>六三，上九之配也。二與四嘗有之矣，“不克訟”而歸於上九。上九之得之也，譬之鞶帶，奪諸其人之身而已，服之於人情有赧焉，故終朝三褫之。既服之矣，則又褫之，愧而不安之甚也。二與四，訟不勝者也，然且終無眚與吉也；上九，訟而勝者也，然且有三褫之辱，何也？曰：此止訟之道也。夫使勝者自多其勝以誇其能，不勝者自恥其不勝以遂其惡，則訟之禍，吾不知其所止矣。故勝者褫服，不勝者安貞無眚，止訟之道也。</p>',20)])])}const f=a(o,[["render",r]]);export{m as __pageData,f as default};
